\begin{ex}%[9D1N2-2]
Cho $\begin{cases}
2 x + y={-3}\quad(1)\\ 
        2 x - 2y={-3} \quad(2)
\end{cases}$. Nhân hai vế của phương trình $(1)$ với $-2$ ta được phương trình mới là: 
\choice
{ \True $- 4 x - 2 y={6}$ }
   { $- 6 x - 2 y={6}$ }
     { $ - 6 x - 2 y={6}$ }
    { $ - 4 x - 2 y={7}$ }
\loigiai{
Từ phương trình $(1)$ rút $y = - 2 x - 3$, thế vào phương trình $(2)$ thu được phương trình theo $x$: $6 x + 9 = 0$.\\
Vậy hệ phương trình có nghiệm duy nhất $(x; y) = (- \frac{3}{2}; 0)$.
}\end{ex}

\begin{ex}%[9D1N2-2]
Cho $\begin{cases}
-5x + y \left(4 - 4 a\right)={- a - 1}\quad(1)\\ 
        - 5x - 2y={-3} \quad(2)
\end{cases}$. Trừ theo vế của phương trình $(1)$ và phương trình $(2)$ ta được phương trình: 
\choice
{ $ y \left(5 - 4 a\right)=2 - a$ }
   { \True $y \left(6 - 4 a\right)=2 - a$ }
     { $ y \left(6 - 4 a\right)=3 - a$ }
    { $y \left(7 - 4 a\right)=1 - a$ }
\loigiai{
Từ phương trình $(1)$ rút $y = \frac{a - 5 x + 1}{4 \left(a - 1\right)}$, thế vào phương trình $(2)$ thu được phương trình theo $x$: $- \frac{a}{2 a - 2} - 5 x + \frac{5 x}{2 a - 2} + 3 - \frac{1}{2 a - 2} = 0$.\\
Vậy hệ phương trình có nghiệm duy nhất $(x; y) = (\frac{5 a - 7}{5 \left(2 a - 3\right)}; \frac{a - 2}{2 \left(2 a - 3\right)})$.
}\end{ex}

\begin{ex}%[9D1N2-2]
Cho $\begin{cases}
x \left(- 4 a - 2\right) - 5y={- 3 a - 2}\quad(1)\\ 
        - x - 5y={1} \quad(2)
\end{cases}$. Trừ theo vế của phương trình $(1)$ và phương trình $(2)$ ta được phương trình: 
\choice
{ $ x \left(a - 1\right)=a - 2$ }
   { $ x \left(a - 2\right)=a - 3$ }
     { \True $x \left(- 4 a - 1\right)=- 3 a - 3$ }
    { $a x=a - 4$ }
\loigiai{
Từ phương trình $(1)$ rút $y = - \frac{4 a x}{5} + \frac{3 a}{5} - \frac{2 x}{5} + \frac{2}{5}$, thế vào phương trình $(2)$ thu được phương trình theo $x$: $4 a x - 3 a + x - 3 = 0$.\\
Vậy hệ phương trình có nghiệm duy nhất $(x; y) = (\frac{3 \left(a + 1\right)}{4 a + 1}; \frac{- 7 a - 4}{5 \left(4 a + 1\right)})$.
}\end{ex}

\begin{ex}%[9D1N2-2]
Cho $\begin{cases}
-3x + y \left(4 a + 2\right)={- 4 a - 4}\quad(1)\\ 
        - 3x - y={-3} \quad(2)
\end{cases}$. Trừ theo vế của phương trình $(1)$ và phương trình $(2)$ ta được phương trình: 
\choice
{ $ y \left(4 a + 2\right)=- 4 a - 1$ }
   { \True $y \left(4 a + 3\right)=- 4 a - 1$ }
     { $y \left(4 a + 4\right)=- 4 a - 2$ }
    { $ y \left(4 a + 3\right)=- 4 a$ }
\loigiai{
Từ phương trình $(1)$ rút $y = \frac{- 4 a + 3 x - 4}{2 \left(2 a + 1\right)}$, thế vào phương trình $(2)$ thu được phương trình theo $x$: $\frac{4 a}{4 a + 2} - 3 x - \frac{3 x}{4 a + 2} + 3 + \frac{4}{4 a + 2} = 0$.\\
Vậy hệ phương trình có nghiệm duy nhất $(x; y) = (\frac{2 \left(8 a + 5\right)}{3 \left(4 a + 3\right)}; \frac{- 4 a - 1}{4 a + 3})$.
}\end{ex}

\begin{ex}%[9D1N2-2]
Cho $\begin{cases}
- x + y \left(a + 3\right)={- 3 a - 2}\quad(1)\\ 
        - x - 3y={2} \quad(2)
\end{cases}$. Trừ theo vế của phương trình $(1)$ và phương trình $(2)$ ta được phương trình: 
\choice
{ $y \left(a + 7\right)=- 3 a - 5$ }
   { $ y \left(a + 6\right)=- 3 a - 3$ }
     { \True $y \left(a + 6\right)=- 3 a - 4$ }
    { $ y \left(a + 5\right)=- 3 a - 4$ }
\loigiai{
Từ phương trình $(1)$ rút $y = \frac{- 3 a + x - 2}{a + 3}$, thế vào phương trình $(2)$ thu được phương trình theo $x$: $\frac{9 a}{a + 3} - x - \frac{3 x}{a + 3} - 2 + \frac{6}{a + 3} = 0$.\\
Vậy hệ phương trình có nghiệm duy nhất $(x; y) = (\frac{7 a}{a + 6}; \frac{- 3 a - 4}{a + 6})$.
}\end{ex}

